public class Main {
    // Cross product of AB and AC. Only multiply and subtract, so it is exact.
    static long cross(long ax, long ay, long bx, long by, long cx, long cy) {
        return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    }

    public static void main(String[] args) {
        // Each row is A, B, C as ax, ay, bx, by, cx, cy.
        long[][] tests = {{0, 0, 4, 0, 2, 3}, {0, 0, 4, 0, 2, -3}, {0, 0, 2, 2, 5, 5}, {1, 1, 1, 5, 0, 3}};
        for (long[] t : tests) {
            long c = cross(t[0], t[1], t[2], t[3], t[4], t[5]);
            // Positive = left turn, negative = right turn, zero = collinear.
            String turn = c > 0 ? "left turn" : (c < 0 ? "right turn" : "collinear");
            System.out.println("A(" + t[0] + "," + t[1] + ") B(" + t[2] + "," + t[3] + ") C(" + t[4] + "," + t[5]
                    + "): cross = " + c + " -> " + turn);
        }
        // The last test has a vertical line A->B: a slope would divide by zero.
        // Time O(1) per test, space O(1).
    }
}

