public class Main {
    // Sign of the cross product: 1 = left turn, -1 = right turn, 0 = collinear.
    static int orient(long ax, long ay, long bx, long by, long cx, long cy) {
        long c = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
        return c > 0 ? 1 : (c < 0 ? -1 : 0);
    }

    // C is known to be collinear with A-B: is it inside the bounding box of A-B?
    static boolean inBox(long ax, long ay, long bx, long by, long cx, long cy) {
        return Math.min(ax, bx) <= cx && cx <= Math.max(ax, bx) && Math.min(ay, by) <= cy && cy <= Math.max(ay, by);
    }

    static boolean intersect(long[] s) {
        long p1x = s[0], p1y = s[1], p2x = s[2], p2y = s[3], q1x = s[4], q1y = s[5], q2x = s[6], q2y = s[7];
        int o1 = orient(p1x, p1y, p2x, p2y, q1x, q1y), o2 = orient(p1x, p1y, p2x, p2y, q2x, q2y);
        int o3 = orient(q1x, q1y, q2x, q2y, p1x, p1y), o4 = orient(q1x, q1y, q2x, q2y, p2x, p2y);
        // General case: each segment has the other's ends on different sides.
        if (o1 != o2 && o3 != o4) return true;
        // Collinear cases: an end point lies on the other segment.
        if (o1 == 0 && inBox(p1x, p1y, p2x, p2y, q1x, q1y)) return true;
        if (o2 == 0 && inBox(p1x, p1y, p2x, p2y, q2x, q2y)) return true;
        if (o3 == 0 && inBox(q1x, q1y, q2x, q2y, p1x, p1y)) return true;
        return o4 == 0 && inBox(q1x, q1y, q2x, q2y, p2x, p2y);
    }

    public static void main(String[] args) {
        long[][] tests = {{0, 0, 4, 4, 0, 4, 4, 0}, {0, 0, 4, 0, 2, 0, 2, 3}, {0, 0, 2, 0, 3, 0, 5, 0},
                          {0, 0, 3, 0, 2, 0, 5, 0}, {0, 0, 4, 0, 0, 1, 4, 1}};
        String[] names = {"crossing", "T-shaped touch", "collinear, apart", "collinear, overlapping", "parallel"};
        for (int i = 0; i < tests.length; i++) {
            long[] s = tests[i];
            System.out.println("(" + s[0] + "," + s[1] + ")-(" + s[2] + "," + s[3] + ") and (" + s[4] + "," + s[5]
                    + ")-(" + s[6] + "," + s[7] + ") [" + names[i] + "]: " + (intersect(s) ? "intersect" : "do not intersect"));
        }
        // Time O(1) per pair, space O(1).
    }
}

