import java.util.*;

public class Main {
    static long cross(long[] a, long[] b, long[] c) {
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    }

    static String show(List<long[]> pts) {
        StringBuilder sb = new StringBuilder();
        for (long[] p : pts) sb.append(" (").append(p[0]).append(",").append(p[1]).append(")");
        return sb.toString();
    }

    public static void main(String[] args) {
        long[][] input = {{0, 0}, {4, 0}, {4, 4}, {0, 4}, {2, 2}, {1, 3}, {2, 0}, {3, 1}};
        List<long[]> pts = new ArrayList<>(Arrays.asList(input));
        System.out.println("Points:" + show(pts));
        // Step 1: sort by x, then by y.
        pts.sort((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        List<long[]> hull = new ArrayList<>();
        // Pass 0 builds the lower hull left to right, pass 1 the upper hull right to left.
        for (int pass = 0; pass < 2; pass++) {
            int start = hull.size();
            for (int i = 0; i < pts.size(); i++) {
                long[] p = pass == 0 ? pts.get(i) : pts.get(pts.size() - 1 - i);
                // Pop while the last two points and p do not make a left turn.
                while (hull.size() >= start + 2 && cross(hull.get(hull.size() - 2), hull.get(hull.size() - 1), p) <= 0)
                    hull.remove(hull.size() - 1);
                hull.add(p);
            }
            hull.remove(hull.size() - 1); // the last point starts the next chain
        }
        System.out.println("Hull (counter-clockwise):" + show(hull));
        // Time O(N log N) for the sort, the two scans are O(N); space O(N).
    }
}

