#include <bits/stdc++.h>
using namespace std;
typedef pair<long long, long long> P;

long long cross(P a, P b, P c) {
    return (b.first - a.first) * (c.second - a.second) - (b.second - a.second) * (c.first - a.first);
}

string show(const vector<P>& pts) {
    string s;
    for (auto& p : pts) s += " (" + to_string(p.first) + "," + to_string(p.second) + ")";
    return s;
}

int main() {
    vector<P> pts = {{0, 0}, {4, 0}, {4, 4}, {0, 4}, {2, 2}, {1, 3}, {2, 0}, {3, 1}};
    cout << "Points:" << show(pts) << "\n";
    // Step 1: sort by x, then by y (pairs sort that way).
    sort(pts.begin(), pts.end());
    vector<P> hull;
    int n = pts.size();
    // Pass 0 builds the lower hull left to right, pass 1 the upper hull right to left.
    for (int pass = 0; pass < 2; pass++) {
        size_t start = hull.size();
        for (int i = 0; i < n; i++) {
            P p = pass == 0 ? pts[i] : pts[n - 1 - i];
            // Pop while the last two points and p do not make a left turn.
            while (hull.size() >= start + 2 && cross(hull[hull.size() - 2], hull.back(), p) <= 0) hull.pop_back();
            hull.push_back(p);
        }
        hull.pop_back(); // the last point starts the next chain
    }
    cout << "Hull (counter-clockwise):" << show(hull) << "\n";
    // Time O(N log N) for the sort, the two scans are O(N); space O(N).
    return 0;
}

