class Program {
    static long Cross(long[] a, long[] b, long[] c) {
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    }

    static string Show(List<long[]> pts) {
        StringBuilder sb = new StringBuilder();
        foreach (long[] p in pts) sb.Append(" (" + p[0] + "," + p[1] + ")");
        return sb.ToString();
    }

    static void Main() {
        List<long[]> pts = new List<long[]> {
            new long[] {0, 0}, new long[] {4, 0}, new long[] {4, 4}, new long[] {0, 4},
            new long[] {2, 2}, new long[] {1, 3}, new long[] {2, 0}, new long[] {3, 1}
        };
        Console.WriteLine("Points:" + Show(pts));
        // Step 1: sort by x, then by y.
        pts.Sort((a, b) => a[0] != b[0] ? a[0].CompareTo(b[0]) : a[1].CompareTo(b[1]));
        List<long[]> hull = new List<long[]>();
        // Pass 0 builds the lower hull left to right, pass 1 the upper hull right to left.
        for (int pass = 0; pass < 2; pass++) {
            int start = hull.Count;
            for (int i = 0; i < pts.Count; i++) {
                long[] p = pass == 0 ? pts[i] : pts[pts.Count - 1 - i];
                // Pop while the last two points and p do not make a left turn.
                while (hull.Count >= start + 2 && Cross(hull[hull.Count - 2], hull[hull.Count - 1], p) <= 0)
                    hull.RemoveAt(hull.Count - 1);
                hull.Add(p);
            }
            hull.RemoveAt(hull.Count - 1); // the last point starts the next chain
        }
        Console.WriteLine("Hull (counter-clockwise):" + Show(hull));
        // Time O(N log N) for the sort, the two scans are O(N); space O(N).
    }
}

