        int start = 0;
        for (int i = 1; i < n; i++) if (pts[i][0] < pts[start][0]) start = i;
        StringBuilder out = new StringBuilder("Hull:");
        int cur = start, h = 0, tests = 0;
        do {
            out.append(" (" + pts[cur][0] + "," + pts[cur][1] + ")");
