public class Main {
    // Returns twice the signed area: positive for counter-clockwise order.
    static long twiceArea(long[] xs, long[] ys) {
        long sum = 0;
        int n = xs.length;
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n; // wrap around to the first vertex
            sum += xs[i] * ys[j] - xs[j] * ys[i];
        }
        return sum;
    }

    static void report(String name, long[] xs, long[] ys) {
        StringBuilder sb = new StringBuilder(name + ":");
        for (int i = 0; i < xs.length; i++) sb.append(" (" + xs[i] + "," + ys[i] + ")");
        long t = twiceArea(xs, ys);
        // Keep 2*area as an integer; divide only when printing.
        System.out.println(sb + " -> signed 2*area = " + t + ", area = " + Math.abs(t) / 2);
    }

    public static void main(String[] args) {
        report("Rectangle, counter-clockwise", new long[] {0, 4, 4, 0}, new long[] {0, 0, 3, 3});
        report("Rectangle, clockwise", new long[] {0, 0, 4, 4}, new long[] {0, 3, 3, 0});
        // Same four corners in a crossing order: the two lobes cancel out.
        report("Bow-tie (self-intersecting)", new long[] {0, 4, 4, 0}, new long[] {0, 3, 0, 3});
        // Time O(N), space O(1).
    }
}

