public class Main {
    static long[] px = {0, 6, 6, 3, 0}, py = {0, 0, 6, 3, 6}; // a square with a notch cut in the top

    static long cross(long ax, long ay, long bx, long by, long cx, long cy) {
        return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    }

    static String locate(long x, long y) {
        int n = px.length, crossings = 0;
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            long ax = px[i], ay = py[i], bx = px[j], by = py[j];
            // On the edge itself: collinear and inside the edge's bounding box.
            if (cross(ax, ay, bx, by, x, y) == 0 && Math.min(ax, bx) <= x && x <= Math.max(ax, bx)
                    && Math.min(ay, by) <= y && y <= Math.max(ay, by)) return "on the boundary";
            if (ay > by) { long t = ax; ax = bx; bx = t; t = ay; ay = by; by = t; } // make A the lower end
            // Half-open rule: count the edge only if low.y <= y < high.y (skips horizontal edges).
            // The ray to the right crosses it when the point is left of the upward edge.
            if (ay <= y && y < by && cross(ax, ay, bx, by, x, y) > 0) crossings++;
        }
        return crossings % 2 == 1 ? "inside" : "outside"; // odd number of crossings = inside
    }

    public static void main(String[] args) {
        System.out.println("Polygon: (0,0) (6,0) (6,6) (3,3) (0,6)");
        long[][] tests = {{1, 1}, {3, 4}, {1, 3}, {7, 3}, {6, 2}, {3, 3}};
        for (long[] t : tests) System.out.println("Point (" + t[0] + "," + t[1] + "): " + locate(t[0], t[1]));
        // Point (1,3) is the tricky one: its ray passes exactly through the vertex (3,3).
        // Time O(N) per query, space O(1).
    }
}

