public class Main {
    static long seed = 42;

    // Small fixed random generator so every language prints the same numbers.
    static int rnd() {
        seed = seed * 48271 % 2147483647;
        return (int) seed;
    }

    public static void main(String[] args) {
        int n = 6, k = 2, trials = 30000;
        int[] kept = new int[n + 1];
        for (int t = 0; t < trials; t++) {
            int[] res = new int[k];
            for (int i = 0; i < n; i++) {       // the stream is the items 1..6, index i = 0..5
                int item = i + 1;
                if (i < k) {
                    res[i] = item;              // the first k items fill the reservoir
                } else {
                    int j = rnd() % (i + 1);    // j is uniform in [0, i], i included
                    if (j < k) res[j] = item;   // happens with probability k/(i+1)
                }
            }
            for (int x : res) kept[x]++;
        }
        System.out.println("Stream 1..6, sample size 2, " + trials + " runs. Expected about "
                + trials * k / n + " each.");
        for (int item = 1; item <= n; item++) System.out.println("item " + item + " kept " + kept[item] + " times");
        // Time O(N) per pass over the stream, space O(k).
    }
}

