import java.util.*;

public class Main {
    static long seed = 42;
    static double[] key = new double[8];

    // Small fixed random generator so every language prints the same numbers.
    static double rnd01() {
        seed = seed * 48271 % 2147483647;
        return seed / 2147483647.0;
    }

    // Keep the k ids with the largest keys (a min-heap of size k does this on a real stream).
    static List<Integer> topK(List<Integer> ids, int k) {
        List<Integer> copy = new ArrayList<>(ids);
        copy.sort((a, b) -> Double.compare(key[b], key[a]));
        return new ArrayList<>(copy.subList(0, k));
    }

    public static void main(String[] args) {
        int[] weight = {1, 1, 2, 1, 8, 1, 1, 6};
        int k = 3;
        System.out.println("Weights of items 0..7: " + Arrays.toString(weight) + ", sample size " + k);
        // A-Res: key = u^(1/weight). A heavy item gets a key close to 1.
        for (int i = 0; i < 8; i++) key[i] = Math.pow(rnd01(), 1.0 / weight[i]);
        List<Integer> a = topK(Arrays.asList(0, 1, 2, 3), k); // server A saw items 0..3
        List<Integer> b = topK(Arrays.asList(4, 5, 6, 7), k); // server B saw items 4..7
        List<Integer> both = new ArrayList<>(a);
        both.addAll(b);
        List<Integer> merged = topK(both, k);                 // merge = top-k of the two local top-k lists
        List<Integer> global = topK(Arrays.asList(0, 1, 2, 3, 4, 5, 6, 7), k);
        System.out.println("Server A keeps " + a + ", server B keeps " + b);
        System.out.println("Merged sample " + merged + ", one-machine sample " + global);
        System.out.println("Same result: " + (merged.equals(global) ? "yes" : "no"));
        // Time O(N log k) with heaps (this demo sorts), space O(k) per server.
    }
}

