import java.util.*;

public class Main {
    static void swap(char[] a, int i, int j) { char t = a[i]; a[i] = a[j]; a[j] = t; }

    static void print(String name, Map<String, Integer> count, int runs) {
        StringBuilder sb = new StringBuilder(name + " (" + runs + " equally likely runs):");
        for (Map.Entry<String, Integer> e : count.entrySet()) sb.append(" " + e.getKey() + "=" + e.getValue());
        System.out.println(sb);
    }

    public static void main(String[] args) {
        System.out.println("Shuffling ABC: how many runs end in each order?");
        // Fisher-Yates: i = 2 picks j from 0..2, then i = 1 picks j from 0..1 -> 3*2 = 6 runs.
        Map<String, Integer> fair = new TreeMap<>();
        for (int j2 = 0; j2 <= 2; j2++)
            for (int j1 = 0; j1 <= 1; j1++) {
                char[] a = {'A', 'B', 'C'};
                swap(a, 2, j2);
                swap(a, 1, j1);
                fair.merge(new String(a), 1, Integer::sum);
            }
        // Obvious version: every i picks j from 0..2 -> 3*3*3 = 27 runs.
        Map<String, Integer> naive = new TreeMap<>();
        for (int j0 = 0; j0 <= 2; j0++)
            for (int j1 = 0; j1 <= 2; j1++)
                for (int j2 = 0; j2 <= 2; j2++) {
                    char[] a = {'A', 'B', 'C'};
                    swap(a, 0, j0);
                    swap(a, 1, j1);
                    swap(a, 2, j2);
                    naive.merge(new String(a), 1, Integer::sum);
                }
        print("Fisher-Yates", fair, 6);
        print("Obvious version", naive, 27);
        // 27 cannot be split evenly over 6 orders, so the obvious version must be biased.
        // A real Fisher-Yates shuffle takes O(N) time and O(1) extra space.
    }
}

