        int old;
        count.TryGetValue(order, out old);
        count[order] = old + 1;
    }

    static void Show(string name, SortedDictionary<string, int> count, int runs) {
        StringBuilder sb = new StringBuilder(name + " (" + runs + " equally likely runs):");
        foreach (KeyValuePair<string, int> e in count) sb.Append(" " + e.Key + "=" + e.Value);
