        SortedDictionary<string, int> fair = new SortedDictionary<string, int>(StringComparer.Ordinal);
        for (int j2 = 0; j2 <= 2; j2++)
            for (int j1 = 0; j1 <= 1; j1++) {
                char[] a = {'A', 'B', 'C'};
                Swap(a, 2, j2);
                Swap(a, 1, j1);
                Add(fair, a);
