import java.util.*;

public class Main {
    static long seed = 42;

    // Small fixed random generator so every language prints the same numbers.
    static int rnd() {
        seed = seed * 48271 % 2147483647;
        return (int) seed;
    }

    // Returns the k-th smallest value (k is 0-based). Works on a copy.
    static int select(int[] input, int k) {
        int[] a = input.clone();
        int lo = 0, hi = a.length - 1;
        while (true) {
            int pivot = a[lo + rnd() % (hi - lo + 1)]; // random pivot: no fixed bad input exists
            int lt = lo, i = lo, gt = hi;
            // 3-way partition: [lo, lt) < pivot, [lt, gt] == pivot, (gt, hi] > pivot.
            while (i <= gt) {
                if (a[i] < pivot) { int t = a[lt]; a[lt++] = a[i]; a[i++] = t; }
                else if (a[i] > pivot) { int t = a[gt]; a[gt--] = a[i]; a[i] = t; }
                else i++;
            }
            if (k < lt) hi = lt - 1;        // answer is in the smaller part
            else if (k > gt) lo = gt + 1;   // answer is in the larger part
            else return pivot;              // k falls in the block of equal values
        }
    }

    public static void main(String[] args) {
        int[] a = {7, 2, 9, 4, 4, 1, 8, 4, 6, 3};
        System.out.println("Array: " + Arrays.toString(a));
        for (int k : new int[] {0, 4, 9}) System.out.println("k = " + k + " (0-based): " + select(a, k));
        // Expected time O(N), worst case O(N^2); space O(1) besides the copy.
    }
}

