            else return pivot;              // k falls in the block of equal values
        }
    }

    static void Main() {
        int[] a = {7, 2, 9, 4, 4, 1, 8, 4, 6, 3};
        Console.WriteLine("Array: [" + string.Join(", ", a) + "]");
        foreach (int k in new int[] {0, 4, 9}) Console.WriteLine("k = " + k + " (0-based): " + Select(a, k));
        // Expected time O(N), worst case O(N^2); space O(1) besides the copy.
    }
}

