public class Main {
    // Counts element copies made by n pushes. factor > 0 multiplies the capacity, otherwise step is added.
    static long copies(int n, int factor, int step) {
        long capacity = factor > 0 ? 1 : step, size = 0, copied = 0;
        for (int i = 0; i < n; i++) {
            if (size == capacity) {
                copied += size; // a full array moves every element to the new block
                capacity = factor > 0 ? capacity * factor : capacity + step;
            }
            size++;
        }
        return copied;
    }

    public static void main(String[] args) {
        for (int n : new int[] {1000, 100000}) {
            long dbl = copies(n, 2, 0), add = copies(n, 0, 10);
            System.out.println("N = " + n + " pushes");
            // Total cost = N writes + copies. Doubling: copies are 1 + 2 + 4 + ... < 2N.
            System.out.println("  doubling:  copies = " + dbl + ", total = " + (n + dbl)
                    + ", per push = " + (n + dbl) / n + " (rounded down)");
            // Adding 10 slots each time: copies are 10 + 20 + 30 + ... which grows like N*N/20.
            System.out.println("  add 10:    copies = " + add + ", total = " + (n + add)
                    + ", per push = " + (n + add) / n + " (rounded down)");
        }
        // Doubling: O(1) amortized per push. Fixed step: O(N) amortized per push. Space O(N).
    }
}

