public class Main {
    public static void main(String[] args) {
        int n = 100000;
        System.out.println("N = " + n + " pushes into a doubling array");

        // Version 1: when full, copy everything in one go (amortized O(1), but spiky).
        long cap = 1, size = 0, total = 0, worst = 0;
        for (int i = 0; i < n; i++) {
            long cost = 1;
            if (size == cap) { cost += size; cap *= 2; }
            size++;
            total += cost;
            worst = Math.max(worst, cost);
        }
        System.out.println("Copy all at once: total work = " + total + ", worst single push = " + worst);

        // Version 2: when full, allocate the bigger block but move only 2 old elements per push.
        cap = 1; size = 0; total = 0; worst = 0;
        long toMove = 0; // old elements still waiting in the old block
        for (int i = 0; i < n; i++) {
            long cost = 1;
            long moved = Math.min(2, toMove); // a small, fixed slice of the migration
            toMove -= moved;
            cost += moved;
            if (size == cap) { toMove = size; cap *= 2; } // start a new migration, copy nothing yet
            size++;
            total += cost;
            worst = Math.max(worst, cost);
        }
        System.out.println("Incremental copy: total work = " + total + ", worst single push = " + worst);
        // Same O(N) total, but the worst case per push drops from O(N) to O(1).
        // Price: two blocks are alive during a migration, so more memory.
    }
}

