public class Main {
    static final int MAXL = 4, CAP = 16;
    static int[] key = new int[CAP];
    static int[][] next = new int[CAP][MAXL]; // next[node][level]; node 0 is the head, -1 means "none"
    static int count = 1;
    static long seed = 42;

    static int rnd() { // small fixed generator so every language prints the same list
        seed = seed * 48271 % 2147483647;
        return (int) seed;
    }

    // Walk right while the next key is smaller, then drop one level. Returns the node before k on level 0.
    static int findBefore(int k, int[] update) {
        int x = 0;
        for (int l = MAXL - 1; l >= 0; l--) {
            while (next[x][l] != -1 && key[next[x][l]] < k) x = next[x][l];
            update[l] = x; // last node before k on this level
        }
        return x;
    }

    static void insert(int k) {
        int[] update = new int[MAXL];
        findBefore(k, update);
        int lvl = 1;
        while (lvl < MAXL && rnd() % 2 == 0) lvl++; // coin flips decide the tower height
        int node = count++;
        key[node] = k;
        for (int l = 0; l < lvl; l++) { // splice into each level: no rotations needed
            next[node][l] = next[update[l]][l];
            next[update[l]][l] = node;
        }
    }

    static boolean contains(int k) {
        int c = next[findBefore(k, new int[MAXL])][0];
        return c != -1 && key[c] == k;
    }

    public static void main(String[] args) {
        for (int[] row : next) java.util.Arrays.fill(row, -1);
        int[] keys = {30, 10, 50, 20, 40, 60, 25};
        System.out.println("Insert order: " + java.util.Arrays.toString(keys));
        for (int k : keys) insert(k);
        for (int l = MAXL - 1; l >= 0; l--) {
            StringBuilder sb = new StringBuilder("Level " + l + ":");
            for (int x = next[0][l]; x != -1; x = next[x][l]) sb.append(" " + key[x]);
            System.out.println(sb);
        }
        for (int k : new int[] {40, 35}) System.out.println("search " + k + ": " + (contains(k) ? "found" : "not found"));
        // Expected O(log N) per search and insert, O(N) expected space.
    }
}

