    array<int, MAXL> update{};
    int x = 0;
    for (int l = MAXL - 1; l >= 0; l--) {
        while (nxt[x][l] != -1 && keyOf[nxt[x][l]] < k) x = nxt[x][l];
        update[l] = x; // last node before k on this level
    }
    return update;
}

