    nxt.push_back({-1, -1, -1, -1});
    int node = keyOf.size() - 1;
    for (int l = 0; l < lvl; l++) { // splice into each level: no rotations needed
        nxt[node][l] = nxt[update[l]][l];
        nxt[update[l]][l] = node;
    }
