    cout << "integers (x10), cross = " << e << ": " << (e == 0 ? "collinear" : "NOT collinear") << "\n";
    // The same effect in one line: 0.1 + 0.2 is not 0.3 in binary floating point.
    volatile double a = 0.1, b = 0.2; // volatile stops the compiler from folding the sum
    cout << "0.1 + 0.2 == 0.3 ? " << (a + b == 0.3 ? "yes" : "no")
         << "   1 + 2 == 3 ? " << (1 + 2 == 3 ? "yes" : "no") << "\n";
    // Time O(1), space O(1).
    return 0;
}

