using System;

class Program {
    static double CrossD(double ax, double ay, double bx, double by, double cx, double cy) {
        return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    }

    static long CrossL(long ax, long ay, long bx, long by, long cx, long cy) {
        return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    }

    static void Main() {
        Console.WriteLine("Points A(0.1,0.3) B(0.2,0.6) C(0.3,0.9) all lie on the line y = 3x");
        // 1) Plain doubles: 0.1, 0.3, 0.9 ... cannot be stored exactly, so the result is a tiny non-zero number.
        double d = CrossD(0.1, 0.3, 0.2, 0.6, 0.3, 0.9);
        Console.WriteLine("double, test == 0:       " + (d == 0 ? "collinear" : "NOT collinear (wrong)"));
        // 2) Doubles with a tolerance: works here, but the tolerance is a guess.
        Console.WriteLine("double, test |x| < 1e-9: " + (Math.Abs(d) < 1e-9 ? "collinear" : "NOT collinear (wrong)"));
        // 3) Scale by 10 and use integers: every step is exact.
        long e = CrossL(1, 3, 2, 6, 3, 9);
        Console.WriteLine("integers (x10), cross = " + e + ": " + (e == 0 ? "collinear" : "NOT collinear"));
        // The same effect in one line: 0.1 + 0.2 is not 0.3 in binary floating point.
        double a = 0.1, b = 0.2;
        Console.WriteLine("0.1 + 0.2 == 0.3 ? " + (a + b == 0.3 ? "yes" : "no")
            + "   1 + 2 == 3 ? " + (1 + 2 == 3 ? "yes" : "no"));
        // Time O(1), space O(1).
    }
}

