public class Main {
    static int[] parent, size;

    // Find the root, then point every node on the path straight at it.
    static int find(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];
        while (parent[x] != root) { int up = parent[x]; parent[x] = root; x = up; }
        return root;
    }

    // Returns false if a and b were already in the same set.
    static boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra; // hang the smaller tree under the bigger one
        size[ra] += size[rb];
        return true;
    }

    public static void main(String[] args) {
        int n = 8;
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        int components = n;
        int[][] edges = {{0, 1}, {2, 3}, {1, 3}, {4, 5}, {6, 7}, {5, 7}, {0, 3}};
        for (int[] e : edges) {
            boolean merged = union(e[0], e[1]);
            if (merged) components--;
            System.out.println("union(" + e[0] + "," + e[1] + "): " + (merged ? "merged" : "already together")
                    + ", components = " + components);
        }
        int[][] queries = {{0, 2}, {0, 4}, {4, 6}};
        for (int[] q : queries)
            System.out.println("connected(" + q[0] + "," + q[1] + "): " + (find(q[0]) == find(q[1]) ? "yes" : "no"));
        // M operations cost O(M * alpha(N)) in total (amortized, almost constant each); space O(N).
    }
}

