#include <bits/stdc++.h>
using namespace std;

vector<int> parent, sz;

// Find the root, then point every node on the path straight at it.
int find(int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];
    while (parent[x] != root) { int up = parent[x]; parent[x] = root; x = up; }
    return root;
}

// Returns false if a and b were already in the same set.
bool unite(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra == rb) return false;
    if (sz[ra] < sz[rb]) swap(ra, rb);
    parent[rb] = ra; // hang the smaller tree under the bigger one
    sz[ra] += sz[rb];
    return true;
}

int main() {
    int n = 8;
    parent.resize(n);
    sz.assign(n, 1);
    for (int i = 0; i < n; i++) parent[i] = i;
    int components = n;
    vector<pair<int, int>> edges = {{0, 1}, {2, 3}, {1, 3}, {4, 5}, {6, 7}, {5, 7}, {0, 3}};
    for (auto& e : edges) {
        bool merged = unite(e.first, e.second);
        if (merged) components--;
        cout << "union(" << e.first << "," << e.second << "): " << (merged ? "merged" : "already together")
             << ", components = " << components << "\n";
    }
    vector<pair<int, int>> queries = {{0, 2}, {0, 4}, {4, 6}};
    for (auto& q : queries)
        cout << "connected(" << q.first << "," << q.second << "): " << (find(q.first) == find(q.second) ? "yes" : "no") << "\n";
    // M operations cost O(M * alpha(N)) in total (amortized, almost constant each); space O(N).
    return 0;
}

